// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0 && tos.length <= 4);
        for (uint i = 0; i < tos.length; i++) vm.assume(tos[i] != address(0));
        bool ok = c.transfer(from, address(this), tos, v);
        assertTrue(ok);
    }
}
